import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('passes valid input with extra properties through to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    let capturedInput: Record<string, unknown> | undefined;

    registry.register(
      {
        name: 'echo',
        description: 'Echoes input',
        inputSchema: {
          type: 'object',
          properties: {foo: {type: 'string'}},
        },
      },
      async input => {
        capturedInput = input;
        return 'ok';
      }
    );

    const input = {foo: 'bar', extra: 123};
    await registry.execute('echo', input);

    expect(capturedInput).toEqual(input);
  });

  it('throws Unknown tool for an unregistered name', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('missing', {})).rejects.toThrow('Unknown tool: missing');
  });

  it('compiles a static schema once across multiple execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaReadCount = 0;
    const definition = {
      name: 'static_tool',
      description: 'Test static compilation',
      get inputSchema() {
        schemaReadCount += 1;
        return {type: 'object'};
      },
    };

    registry.register(definition, async () => 'ok');
    // Once at register time (to verify) and once to store the compiled validator
    const initialReads = schemaReadCount;

    for (let i = 0; i < 10; i++) {
      await registry.execute('static_tool', {});
    }

    expect(schemaReadCount).toBe(initialReads);
  });

  it('validates dynamic tools against the schema current at the call time and caches them', async () => {
    const registry = new ToolRegistry();
    let currentType = 'string';
    const dynamicDefinition = () => ({
      name: 'dynamic_tool',
      description: 'Test dynamic compilation',
      inputSchema: {
        type: 'object',
        properties: {val: {type: currentType}},
      },
    });

    registry.register(dynamicDefinition, async () => 'ok');

    // First call: string
    const res1 = await registry.execute('dynamic_tool', {val: 'hello'});
    expect(res1.result).toBe('ok');
    const res2 = await registry.execute('dynamic_tool', {val: 123});
    expect(res2.result).toContain('Validation failed');

    // Change schema to number
    currentType = 'number';
    const res3 = await registry.execute('dynamic_tool', {val: 123});
    expect(res3.result).toBe('ok');
    const res4 = await registry.execute('dynamic_tool', {val: 'hello'});
    expect(res4.result).toContain('Validation failed');
  });
});
